        TRY_CAST(REPLACE(CAST(created_at AS VARCHAR), 'T', ' ') AS TIMESTAMP) AS placed_at,
        TRY_CAST(quantity AS BIGINT) AS quantity,
        TRY_CAST(JSON_EXTRACT_SCALAR(variant, '$.sku') AS VARCHAR) AS sku,
        CASE TRY_CAST(financial_status AS VARCHAR)
          WHEN 'pending'
          THEN 'open'
          WHEN 'paid'
          THEN 'closed'
          WHEN 'refunded'
          THEN 'reversed'
          ELSE TRY_CAST(financial_status AS VARCHAR)
        END AS status,
        _ingested_at,
        _load_id,
        _source_row_id,
        TRY_CAST(JSON_EXTRACT_SCALAR(properties, '$.gift_note') AS VARCHAR) IS NULL
        AND (
          NOT JSON_EXTRACT_SCALAR(properties, '$.gift_note') IS NULL
        ) AS _branch_gift_note_coercible,
        TRY_CAST(position AS BIGINT) IS NULL AND (
          NOT position IS NULL
        ) AS _branch_line_no_coercible,
        TRY_CAST(JSON_EXTRACT_SCALAR("order", '$.id') AS VARCHAR) IS NULL
        AND (
          NOT JSON_EXTRACT_SCALAR("order", '$.id') IS NULL
        ) AS _branch_order_id_coercible,
        TRY_CAST(REPLACE(CAST(created_at AS VARCHAR), 'T', ' ') AS TIMESTAMP) IS NULL
        AND (
          NOT created_at IS NULL
        ) AS _branch_placed_at_coercible,
        TRY_CAST(quantity AS BIGINT) IS NULL AND (
          NOT quantity IS NULL
        ) AS _branch_quantity_coercible,
        TRY_CAST(JSON_EXTRACT_SCALAR(variant, '$.sku') AS VARCHAR) IS NULL
        AND (
          NOT JSON_EXTRACT_SCALAR(variant, '$.sku') IS NULL
        ) AS _branch_sku_coercible,
        CASE TRY_CAST(financial_status AS VARCHAR)
          WHEN 'pending'
          THEN 'open'
          WHEN 'paid'
          THEN 'closed'
          WHEN 'refunded'
          THEN 'reversed'
          ELSE TRY_CAST(financial_status AS VARCHAR)
        END IS NULL
        AND (
          NOT financial_status IS NULL
        ) AS _branch_status_coercible,
        NOT CASE TRY_CAST(financial_status AS VARCHAR)
          WHEN 'pending'
          THEN 'open'
          WHEN 'paid'
          THEN 'closed'
          WHEN 'refunded'
          THEN 'reversed'
          ELSE TRY_CAST(financial_status AS VARCHAR)
        END IN ('closed', 'open', 'reversed') AS _branch_status_in_enum,
        'shopify__order_lines' AS _source
