        TRY_CAST(item_index AS BIGINT) AS line_no,
        TRY_CAST(order_number AS VARCHAR) AS order_id,
        TRY_CAST(REPLACE(CAST(created AS VARCHAR), 'T', ' ') AS TIMESTAMP) AS placed_at,
        TRY_CAST(qty AS BIGINT) AS quantity,
        TRY_CAST(product_sku AS VARCHAR) AS sku,
        CASE TRY_CAST(state AS VARCHAR)
          WHEN 'PROCESSING'
          THEN 'open'
          WHEN 'COMPLETE'
          THEN 'closed'
          ELSE TRY_CAST(state AS VARCHAR)
        END AS status,
        _ingested_at,
        _load_id,
        _source_row_id,
        FALSE AS _branch_gift_note_coercible,
        TRY_CAST(item_index AS BIGINT) IS NULL AND (
          NOT item_index IS NULL
        ) AS _branch_line_no_coercible,
        TRY_CAST(order_number AS VARCHAR) IS NULL AND (
          NOT order_number IS NULL
        ) AS _branch_order_id_coercible,
        TRY_CAST(REPLACE(CAST(created AS VARCHAR), 'T', ' ') AS TIMESTAMP) IS NULL
        AND (
          NOT created IS NULL
        ) AS _branch_placed_at_coercible,
        TRY_CAST(qty AS BIGINT) IS NULL AND (
          NOT qty IS NULL
        ) AS _branch_quantity_coercible,
        TRY_CAST(product_sku AS VARCHAR) IS NULL AND (
          NOT product_sku IS NULL
        ) AS _branch_sku_coercible,
        CASE TRY_CAST(state AS VARCHAR)
          WHEN 'PROCESSING'
          THEN 'open'
          WHEN 'COMPLETE'
          THEN 'closed'
          ELSE TRY_CAST(state AS VARCHAR)
        END IS NULL
        AND (
          NOT state IS NULL
        ) AS _branch_status_coercible,
        NOT CASE TRY_CAST(state AS VARCHAR)
          WHEN 'PROCESSING'
          THEN 'open'
          WHEN 'COMPLETE'
          THEN 'closed'
          ELSE TRY_CAST(state AS VARCHAR)
        END IN ('closed', 'open') AS _branch_status_in_enum,
